/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `tr_gerar_alerta_critico` AFTER INSERT ON `medicao` FOR EACH ROW BEGIN
    DECLARE min_val DECIMAL(10,2);
    DECLARE max_val DECIMAL(10,2);
    DECLARE paciente_id INT;

    -- 1. Obter o ID
    SET paciente_id = NEW.Pacientes_idPacientes;

    -- 2. Obter limites (com tratamento se não encontrar)
    SELECT Valor_minimo, Valor_Maximo
    INTO min_val, max_val
    FROM limites_alerta
    WHERE Pacientes_idPacientes = paciente_id
    LIMIT 1;

    -- 3. Verificação de segurança: Só compara se os limites existirem (não forem NULL)
    IF min_val IS NOT NULL AND max_val IS NOT NULL THEN
        
        -- Checar se excede os limites
        IF NEW.valor < min_val OR NEW.valor > max_val THEN
            
            INSERT INTO alertas (geracao, nivel_critico, status, Pacientes_idPacientes)
            VALUES (
                NOW(), 
                'CRITICO', 
                'A',  -- Ajustado para 'A' (Ativo) para manter padrão do projeto
                paciente_id
            );
            
        END IF;
    END IF;
END */;;
