DROP TABLE IF EXISTS `pacientes`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `pacientes` (
  `idPacientes` int NOT NULL AUTO_INCREMENT,
  `Nome` varchar(200) COLLATE utf8mb4_general_ci NOT NULL,
  `idade` int NOT NULL,
  `Data_de_Nascimento` date NOT NULL,
  `CPF` char(14) COLLATE utf8mb4_general_ci NOT NULL,
  `Email` varchar(100) COLLATE utf8mb4_general_ci NOT NULL,
  `Telefone` varchar(20) COLLATE utf8mb4_general_ci NOT NULL,
  `Numero_da_casa` int NOT NULL,
  `Genero` char(1) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `Contato_Emergencial_Nome` varchar(200) COLLATE utf8mb4_general_ci NOT NULL,
  `Contato_Emergencial_Telefone` varchar(45) COLLATE utf8mb4_general_ci NOT NULL,
  `Status` char(1) COLLATE utf8mb4_general_ci NOT NULL,
  `Data_Cadastro` date NOT NULL,
  `Bairros_idBairros` int NOT NULL,
  PRIMARY KEY (`idPacientes`),
  UNIQUE KEY `Email_UNIQUE` (`Email`),
  UNIQUE KEY `CPF_UNIQUE` (`CPF`),
  KEY `fk_Pacientes_Bairros1_idx` (`Bairros_idBairros`),
  CONSTRAINT `fk_Pacientes_Bairros1` FOREIGN KEY (`Bairros_idBairros`) REFERENCES `bairros` (`idBairros`)
) ENGINE=InnoDB AUTO_INCREMENT=1006 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

