/*!50003 DROP PROCEDURE IF EXISTS `SP_Obter_Ultima_Medicao` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `SP_Obter_Ultima_Medicao`(
    IN p_paciente_id INT,
    IN p_tipo_medicao VARCHAR(50)
)
BEGIN
    SELECT 
        P.Nome AS Paciente,
        M.medicao AS Timestamp_Medicao, 
        M.valor AS Valor_Medido, 
        M.unidade_medida AS Unidade
    FROM 
        medicao AS M
    INNER JOIN 
        pacientes AS P ON M.Pacientes_idPacientes = P.idPacientes
    WHERE 
        M.Pacientes_idPacientes = p_paciente_id 
        AND M.tipo_medicao = p_tipo_medicao    
    ORDER BY 
        M.medicao DESC 
    LIMIT 1; 
END ;;
DELIMITER ;
